            prompt: tokens.input ?? 0,
            completion: tokens.output ?? 0,
            total: (tokens.input ?? 0) + (tokens.output ?? 0),
          }
        : undefined,
      cost: assistantMessage?.cost ?? 0,
      raw: JSON.stringify(response),
      sessionId,
    };
  }

